args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?paternalGrandmother ?paternalGrandmotherLabel WHERE {
  {
    ?mother dbo:child dbr:Ahmose-Henutemipet .
    ?mother ?spouseProp ?father .
    FILTER(?spouseProp IN (dbo:spouse, dbp:spouse))
  }
  UNION
  {
    ?father ?childProp1 dbr:Ahmose-Henutemipet .
    FILTER(?childProp1 IN (dbo:child, dbp:issue, dbp:children, dbp:parent, dbp:father))
  }

  ?paternalGrandmother ?childProp2 ?father .
  FILTER(?childProp2 IN (dbo:child, dbp:issue, dbp:children, dbp:parent))

  OPTIONAL {
    ?paternalGrandmother rdfs:label ?paternalGrandmotherLabel .
    FILTER(lang(?paternalGrandmotherLabel) = "en")
  }
}

